def score_band(start, changes, intervals):
    total = start + sum(changes)
    for low, high, label in intervals:
        if low <= total < high:
            return label
    return 'out'

def vowel_flip(text):
    vowels = set('aeiou')
    out = []
    for ch in text:
        out.append(ch.swapcase() if ch.lower() in vowels else ch)
    return ''.join(out)

def run_compress(text):
    if not text:
        return text
    parts = []
    count = 1
    for i in range(1, len(text) + 1):
        if i < len(text) and text[i] == text[i - 1]:
            count += 1
        else:
            parts.append(text[i - 1] + str(count))
            count = 1
    compressed = ''.join(parts)
    return compressed if len(compressed) < len(text) else text

def min_increments_non_decreasing(nums):
    if not nums:
        return 0
    ops = 0
    prev = nums[0]
    for x in nums[1:]:
        if x < prev:
            ops += prev - x
        else:
            prev = x
    return ops
